package ruian

import (
	_ "embed"
	"strconv"
	"strings"
	"sync"
)

// okres.csv is generated by hand once a year (owner decision 2026-11-17): one
// line "obec code;okres name" per municipality, 6,258 lines, UTF-8, LF, sorted by
// code. Source (ČÚZK, CC BY 4.0, data of 2026-10-31): OKRES_KOD per OBEC_KOD in
// strukturovane-CSV/vazby-cr.csv of https://vdp.cuzk.gov.cz/vymenny_format/csv/
// 20261031_strukt_ADR.csv.zip, and the okres names (<oki:Nazev>) from
// https://vdp.cuzk.gov.cz/vymenny_format/soucasna/20261031_ST_UKSH.xml.zip.
// Praha (554782) has no okres code there; Python's rule gives "Hlavní město Praha".
//
//go:embed okres.csv
var okresCSV string

var (
	okresOnce sync.Once
	okresMap  map[int]string
)

// Okres returns the okres name of a municipality code, or "" when unknown.
func Okres(obecCode int) string {
	okresOnce.Do(func() {
		okresMap = map[int]string{}
		for _, line := range strings.Split(okresCSV, "\n") {
			code, name, ok := strings.Cut(strings.TrimSpace(line), ";")
			if n, err := strconv.Atoi(code); ok && err == nil {
				okresMap[n] = name
			}
		}
	})
	return okresMap[obecCode]
}
